const rows = [
  { id: 1, name: 'Ada', active: true, qty: 2 },
  { id: 2, name: 'Lin', active: false, qty: 5 },
  { id: 3, name: 'Ada', active: true, qty: 0 },
]

const names = rows.map((r) => r.name)         // ['Ada', 'Lin', 'Ada']
const live = rows.filter((r) => r.active)     // two rows
const hasZero = rows.some((r) => r.qty === 0) // true — not filter(Boolean)

// ❌ mutates rows and returns the same reference
const broken = rows.sort((a, b) => a.name.localeCompare(b.name))
// broken === rows → true

// ✅ derived view: copy, then filter
const visible = rows
  .toSorted((a, b) => a.name.localeCompare(b.name))
  .filter((r) => r.active)

