const rows = [
  { id: 1, name: 'Ada', active: true, qty: 2 },
  { id: 2, name: 'Lin', active: false, qty: 5 },
  { id: 3, name: 'Ada', active: true, qty: 0 },
]

const names = rows.map((r) => r.name)         // ['Ada', 'Lin', 'Ada']
const live = rows.filter((r) => r.active)     // hai hàng
const hasZero = rows.some((r) => r.qty === 0) // true — không dùng filter(Boolean)

// ❌ thay đổi rows và trả cùng reference
const broken = rows.sort((a, b) => a.name.localeCompare(b.name))
// broken === rows → true

// ✅ dữ liệu dẫn xuất: copy, rồi filter
const visible = rows
  .toSorted((a, b) => a.name.localeCompare(b.name))
  .filter((r) => r.active)

