// ❌ var is function-scoped: every callback sees the last i
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0)
}
// logs: 3, 3, 3  — not 0, 1, 2

// Sequential await does NOT have that bug: each step waits.
for (var j = 0; j < 3; j++) {
  await save(j) // runs 0, then 1, then 2
}

// ✅ let creates a binding per iteration
for (let k = 0; k < 3; k++) {
  setTimeout(() => console.log(k), 0)
}
// logs: 0, 1, 2

const user = { role: 'admin' }
user.role = 'guest' // legal: const is the binding, not a freeze

